// Firehorse data display contract: one way to show a value, everywhere.
//
//   import { resolveValue, textOf } from "@rascode/firehorse/values";
//   resolveValue({ key: "state", semanticType: "status" }, "cell");
//   // → { shape: "option", row: "option.status", variant: "dot", id: "VAL-1.1", group: "VAL-1", ... }
//   textOf({ key: "state", semanticType: "status" }, "active");   // → "Active" (CSV, aria-label, copy, search)
//
// A surface (datatable, table, record table, metric, card, sidecar, form) never decides how a value looks:
// it hands the field to resolveValue() with its context, and draws the variant it gets back.
// The field decides (its semantic type, option set or entity kind); the rule grid in schema/display-rules.json
// decides what to draw in each context; a field may name a variant, a surface never can (rule 5).
// The sixth context, text, is never drawn: it names the plain string a value becomes, and textOf() makes it.
// Rules, semantic types and option sets come from value-rules.js (generated by scripts/value-rules.mjs from
// schema/display-rules.json, schema/semantic-types.json and schema/option-sets.json). Agent doc: agent/components/values.md.
import { rules, semanticTypes, optionSets } from "./value-rules.js";

export { rules, semanticTypes, optionSets };
// The Values parts as markup (W3): renderValue(field, value, context, opts), and the shapes it reads.
export { renderValue, entityOf, fileOf, placeOf, sparkline } from "./value-render.js";

/** The fifteen shapes, in display-rules.json order (series is the 14th, place the 15th). */
export const SHAPES = Object.freeze(Object.keys(rules.shapes));
/** The six contexts: cell, record, card, metric, form, and text (the plain string, never drawn). */
export const CONTEXTS = Object.freeze(Object.keys(rules.contexts));
/** The five contexts a value is drawn in (every context but text). */
export const DRAWN_CONTEXTS = Object.freeze(CONTEXTS.filter((c) => c !== "text"));
/** Empty is a muted em dash, never a blank cell or null (rule 7). */
export const EMPTY = Object.freeze({ ...rules.empty });
/** The five states and their tones: done lime, moving sky, waiting amber, failed rose, ended neutral. */
export const STATES = Object.freeze({ ...rules.states });

const toneByWord = new Map();
for (const [tone, words] of Object.entries(rules.toneMap)) for (const w of words) toneByWord.set(w, tone);

/** The default tone of a status word (the Status chip's map): done lime, moving sky, waiting amber, failed rose, else neutral. */
export function defaultTone(value) {
  return toneByWord.get(String(value ?? "").trim().toLowerCase()) ?? "neutral";
}

/** Computed and system types are read-only: they resolve to their record variant in a form. */
export function isReadOnly(semanticType) {
  if (!semanticType) return false;
  const { prefixes = [], keys = [] } = rules.readOnly ?? {};
  return keys.includes(semanticType) || prefixes.some((p) => semanticType.startsWith(p));
}

/** Is this a value with nothing to show (null, undefined, "", or an empty list)? */
export function isEmpty(value) {
  return value == null || value === "" || (Array.isArray(value) && value.length === 0);
}

/** The avatar kinds (DR2): a person is a circle; an org, an agent and a record are rounded squares. */
export const AVATAR_KINDS = Object.freeze(Object.keys(rules.avatars.kinds));

/**
 * How an entity's avatar is drawn (DR2): data-kind (its shape), its size step, and how many faces a stack shows.
 *   avatarOf("person", "full")  → { kind: "person", shape: "circle", size: "identity", token: "--fh-avatar-identity", max: 3 }
 *   avatarOf("org", "stack")    → { kind: "org", shape: "rounded", size: "inline", token: "--fh-avatar-inline", max: 3 }
 * kind is null for a kind the avatar system does not know: the avatar keeps the default plate and no data-kind.
 */
export function avatarOf(kind, variant = null) {
  const k = kind && rules.avatars.kinds[kind] ? kind : null;
  const size = rules.avatars.identity.includes(variant) ? "identity" : "inline";
  return { kind: k, shape: k ? rules.avatars.kinds[k] : null, size, token: rules.avatars.sizes[size], max: rules.avatars.max };
}

/** At most two letters for an avatar with no image: "Maya Chen" → "MC", "Northwind" → "NO". */
export function initialsOf(name) {
  const words = String(name ?? "").trim().split(/\s+/).filter(Boolean);
  if (!words.length) return "";
  const first = [...words[0]];
  const letters = words.length > 1 ? first[0] + [...words[words.length - 1]][0] : first.slice(0, 2).join("");
  return letters.toUpperCase().slice(0, rules.avatars.initials);
}

const escHtml = (v) => String(v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const entityName = (e) => (e && typeof e === "object" ? String(e.label ?? e.name ?? e.id ?? "") : String(e ?? ""));
const kindAttr = (k) => (k ? ` data-kind="${k}"` : "");

/**
 * The image an entity's avatar shows (the avatar cascade): its own image, else the first image down its fallback
 * chain, { image, label, fallback? } (a model with no mark draws its family's, then its platform's). null: initials.
 */
export function avatarImageOf(entity) {
  for (let e = entity, n = 0; e && typeof e === "object" && n < 4; e = e.fallback, n++) {
    if (e.image) return { image: String(e.image), label: String(e.label ?? e.name ?? "") };
  }
  return null;
}

/**
 * One avatar as markup, with data-kind written from the entity's kind (DR2). Its size comes from the context
 * (components/data/values.css), never from a size class here.
 *   entity  { label | name, image?, initials?, kind?, fallback? } (the Entity of values.d.ts)
 *   opts    { kind (when the entity carries none), alt (true: the image names the entity; default "", the name is beside it) }
 */
export function avatarMarkup(entity, opts = {}) {
  const { kind } = avatarOf(entity?.kind ?? opts.kind);
  const name = entityName(entity);
  const img = avatarImageOf(entity);
  const face = img ? `<img src="${escHtml(img.image)}" alt="${opts.alt ? escHtml(name) : ""}">` : escHtml(String(entity?.initials ?? initialsOf(name)).slice(0, rules.avatars.initials));
  return `<span class="fh-avatar"${kindAttr(kind)} title="${escHtml(name)}">${face}</span>`;
}

/** A stack (DR2): at most three faces, then "+N" at the same size and shape (the first face's kind); one label names them all. */
export function stackMarkup(list = [], opts = {}) {
  const max = opts.max ?? rules.avatars.max;
  const { kind } = avatarOf(list[0]?.kind ?? opts.kind);
  const names = list.map(entityName);
  const rest = list.length - max;
  const label = rest > 0 ? `${names.slice(0, max).join(", ")} and ${rest} more` : names.join(", ");
  const faces = list.slice(0, max).map((e) => avatarMarkup(e, { kind: opts.kind })).join("");
  const more = rest > 0 ? `<span class="fh-avatar fh-avatars__more"${kindAttr(kind)} aria-hidden="true">+${rest}</span>` : "";
  return `<span class="fh-avatars" role="group" aria-label="${escHtml(label)}">${faces}${more}</span>`;
}

const fileNameOf = (f) => (f && typeof f === "object" ? String(f.name ?? f.filename ?? f.label ?? "") : String(f ?? ""));
const fileUrlOf = (f) => (f && typeof f === "object" ? String(f.url ?? f.image ?? f.preview ?? "") : typeof f === "string" ? f : "");
const asFileList = (v) => (Array.isArray(v) ? v : v ? [v] : []);
const fileExtOf = (name) => {
  const base = String(name ?? "").split("/").pop() ?? "";
  const dot = base.lastIndexOf(".");
  return dot > 0 ? base.slice(dot + 1).toUpperCase() : base.slice(0, 3).toUpperCase();
};

/** One image thumb at row height (DR4). */
export function thumbMarkup(file, opts = {}) {
  const name = fileNameOf(file);
  const url = fileUrlOf(file);
  const alt = escHtml(String(file?.alt ?? name));
  const portrait = opts.portrait ? " fh-thumb--portrait" : "";
  const lg = opts.lg ? " fh-thumb--lg" : "";
  if (url) {
    const open = opts.open !== false ? ` data-media-open data-media-url="${escHtml(url)}" data-media-alt="${alt}"` : "";
    return `<button type="button" class="fh-thumb${portrait}${lg}"${open}><img src="${escHtml(url)}" alt="${alt}"></button>`;
  }
  return `<span class="fh-thumb fh-thumb--tile${portrait}${lg}" title="${escHtml(name)}">${escHtml(fileExtOf(name) || "?")}</span>`;
}

/** Side-by-side thumbs with +N (DR4): no overlap. */
export function thumbClusterMarkup(files = [], opts = {}) {
  const max = opts.max ?? rules.avatars.max;
  const list = asFileList(files);
  const names = list.map(fileNameOf);
  const rest = list.length - max;
  const label = rest > 0 ? `${names.slice(0, max).join(", ")} and ${rest} more` : names.join(", ");
  const urls = list.map((f) => fileUrlOf(f)).filter(Boolean);
  const open = urls.length ? ` data-media-cluster="${escHtml(urls.join("|"))}"` : "";
  const faces = list.slice(0, max).map((f) => thumbMarkup(f, { open: true })).join("");
  const more = rest > 0 ? `<span class="fh-thumb fh-thumb--tile fh-thumb--more" aria-hidden="true">+${rest}</span>` : "";
  return `<span class="fh-thumbs-row" role="group" aria-label="${escHtml(label)}"${open}>${faces}${more}</span>`;
}

export function formatBytes(n) {
  const b = Number(n);
  if (!Number.isFinite(b) || b < 0) return "";
  if (b < 1024) return `${b} B`;
  if (b < 1024 * 1024) return `${Math.round(b / 1024)} KB`;
  return `${(b / (1024 * 1024)).toFixed(1)} MB`;
}

/** The ramp step (1 … steps) of the option at index i of n in an ordinal set: the first is 1, the last is the top step. */
export function rampStep(i, n, steps = rules.ramp.steps) {
  if (n <= 1) return steps;
  return 1 + Math.round((i * (steps - 1)) / (n - 1));
}

/**
 * What a field is, before any context: its shape, kind, unit, semantic type, option set and whether it holds several values.
 * Precedence: the field's own shape/kind, then its datatable type alias, then its semantic type, then text.
 * A computed_formula field takes the shape its formula returns (field.resultShape, set per column); text when it has none.
 * field: { key, semanticType?, type? (one of the datatable's 22 types), shape?, kind?, entity?, multiple?, unit?, readOnly?, resultShape?, currencyFrom? }
 */
export function describeField(field = {}) {
  const alias = field.type ? rules.aliases[field.type] : undefined;
  const semanticKey = field.semanticType ?? alias?.semanticType ?? null;
  const semantic = semanticKey ? semanticTypes[semanticKey] : undefined;
  const warnings = [];
  if (field.type && !alias) warnings.push(`unknown datatable type "${field.type}"`);
  if (semanticKey && !semantic) warnings.push(`unknown semantic type "${semanticKey}"`);
  // A value with options never renders as free text (rule 2): a field that brings a set is an option.
  let shape = field.shape ?? alias?.shape ?? semantic?.shape ?? (field.optionSet || Array.isArray(field.options) ? "option" : "text");
  let kind = field.kind ?? field.entity ?? alias?.kind ?? semantic?.kind ?? null;
  const formula = kind === "formula";
  if (formula && field.resultShape != null) {
    if (rules.shapes[field.resultShape]) {
      shape = field.resultShape;
      kind = field.resultKind ?? null;
    } else warnings.push(`unknown result shape "${field.resultShape}", drawn as text`);
  }
  if (!rules.shapes[shape]) {
    warnings.push(`unknown shape "${shape}", drawn as text`);
    shape = "text";
    kind = null;
  }
  let multiple = field.multiple ?? alias?.multiple ?? shape === "options";
  // Several values from a set are the options shape, whatever the field called itself.
  if (shape === "option" && multiple) shape = "options";
  if (shape === "options") multiple = true;
  return {
    shape,
    kind,
    unit: field.unit ?? semantic?.unit ?? null,
    semanticType: semantic ? semanticKey : null,
    alias: alias ? field.type : null,
    multiple: Boolean(multiple),
    readOnly: Boolean(field.readOnly ?? isReadOnly(semanticKey)),
    optionSet: typeof field.optionSet === "string" ? field.optionSet : (semantic?.optionSet ?? null),
    currencyFrom: field.currencyFrom ?? semantic?.currencyFrom ?? null,
    formula,
    display: { ...(alias?.display ?? {}), ...(field.display ?? {}) },
    warnings,
  };
}

/**
 * The option set a field draws from, with every option's tone filled in.
 * Sources, first found: field.optionSet as an object; field.optionSet as a key (opts.optionSets, then the published
 * sets of schema/option-sets.json); field.options (strings or { value, label, tone }); the semantic type's option set
 * (devops.option_sets via display.optionSet); the semantic type's own options (key semantic.<type>).
 * Tones: the option's own; else its state's (a status set); else the default tone map. An ordinal set that is not a
 * status set draws as a ramp: every option gets ramp 1 … steps, in order (decision 6).
 * Returns { key, kind, ordinal, label?, generator?, options: [{ value, label, tone, state?, ramp?, icon?, description?, live? }] } or null.
 */
export function optionSetFor(field = {}, opts = {}) {
  const d = describeField(field);
  const registry = { ...optionSets, ...(opts.optionSets ?? {}) };
  const fromRegistry = (key) => (key && registry[key] ? { key, ...registry[key] } : null);
  let set = null;
  if (field.optionSet && typeof field.optionSet === "object") set = field.optionSet;
  else if (typeof field.optionSet === "string" && registry[field.optionSet]) set = fromRegistry(field.optionSet);
  else if (Array.isArray(field.options)) set = { key: typeof field.optionSet === "string" ? field.optionSet : (field.key ? `field.${field.key}` : null), options: field.options };
  else if (d.semanticType && semanticTypes[d.semanticType].optionSet && registry[semanticTypes[d.semanticType].optionSet]) set = fromRegistry(semanticTypes[d.semanticType].optionSet);
  else if (d.semanticType && semanticTypes[d.semanticType].options) set = { key: `semantic.${d.semanticType}`, options: semanticTypes[d.semanticType].options };
  if (!set) return null;
  const kind = ["status", "choice", "code"].includes(set.kind) ? set.kind : d.kind === "status" ? "status" : "choice";
  const ordinal = Boolean(set.ordinal || d.kind === "ordinal");
  const ramp = ordinal && kind !== "status";
  const n = set.options.length;
  return {
    key: set.key ?? null,
    kind,
    ordinal,
    ...(set.label ? { label: set.label } : {}),
    ...(set.generator ? { generator: set.generator } : {}),
    options: set.options.map((o, i) => {
      const opt = typeof o === "object" && o !== null ? o : { value: o };
      const tone = opt.tone ?? (opt.state ? STATES[opt.state] : null) ?? (ramp ? rules.ramp.hue : kind === "code" ? "neutral" : defaultTone(opt.value));
      return { ...opt, label: opt.label ?? String(opt.value), tone, ...(ramp ? { ramp: rampStep(i, n) } : {}) };
    }),
  };
}

/** The tone of one value in a set: the option's tone, else the default tone map. */
export function toneOf(set, value) {
  const hit = set?.options?.find((o) => String(o.value) === String(value));
  return hit?.tone ?? defaultTone(value);
}

/** The ramp step of one value in an ordinal set, or null when the set has no ramp. */
export function rampOf(set, value) {
  return set?.options?.find((o) => String(o.value) === String(value))?.ramp ?? null;
}

function matches(row, d, count, set) {
  if (row.shape !== d.shape) return false;
  const m = row.match;
  if (!m) return true;
  // An ordinal choice set makes its field ordinal, whatever the field's own kind (decision 6).
  const kind = set?.ordinal && set.kind === "choice" ? "ordinal" : d.kind;
  if (m.kind && !m.kind.includes(kind)) return false;
  if (m.set && !m.set.includes(set?.kind)) return false;
  if (m.multiple !== undefined && m.multiple !== d.multiple) return false;
  if (m.count) {
    if (count == null) return false;
    const [lo, hi] = m.count;
    if ((lo != null && count < lo) || (hi != null && count > hi)) return false;
  }
  return true;
}

/** The grid row a described field falls on (first match in display-rules.json order). */
export function gridRow(d, count = null, set = null) {
  return rules.grid.find((row) => matches(row, d, count, set)) ?? rules.grid.find((row) => row.shape === "text" && !row.match);
}

/** A variant's entry, and the group of the part it is: a variant with `of` is that shape's part of the same ID. */
function variantMeta(shape, variant) {
  const meta = variant ? rules.variants[shape].variants[variant] : null;
  if (!meta) return { meta: null, group: rules.variants[shape].group };
  return { meta, group: meta.of ? rules.variants[meta.of].group : rules.variants[shape].group };
}

/**
 * How to draw a field's value here.
 *   field    the field (see describeField); `display: { cell: "chip" }` names a variant for a context (rule 5)
 *   context  "cell" | "record" | "card" | "metric" | "form" | "text"
 *   mode     "read" | "edit" (default: edit in a form, read elsewhere; text is always read)
 *   opts     { optionSets } a registry of option sets by key, over the published ones
 * Returns { shape, kind, row, context, mode, variant, id (the variant's Index ID, VAL-1.1), label, group, parts, editable, control, readOnly, align,
 *   figures, grouping, mono, max, avatar (an entity's avatarOf(): data-kind, size step, stack max), multiple, unit, currency, currencyFrom, optionSet, ramp, sort, last, excluded, text, formula, empty, source, warnings }.
 * variant is null when the grid leaves the field out of that context (metric for prose, say): the surface skips it.
 * In the text context variant is a text format (rules.textFormats) and id is null; null means the value has no
 * text form (a secret): leave it out of CSV export, aria-label and copy.
 * In edit mode outside a form, the read variant stays and gains its control (rule 6): editable + control.
 */
export function resolveValue(field = {}, context = "cell", mode, opts = {}) {
  if (!rules.contexts[context]) throw new TypeError(`unknown context "${context}" (one of ${CONTEXTS.join(", ")})`);
  mode ??= context === "form" ? "edit" : "read";
  if (!rules.modes.includes(mode)) throw new TypeError(`unknown mode "${mode}" (read or edit)`);
  if (context === "text") mode = "read";
  const d = describeField(field);
  const warnings = [...d.warnings];
  const optionSet = d.shape === "option" || d.shape === "options" ? optionSetFor(field, opts) : null;
  const row = gridRow(d, optionSet ? optionSet.options.length : null, optionSet);
  const family = rules.variants[d.shape];
  let variant = row[context] ?? null;
  let source = "grid";
  // A ratio with a target is a meter in the metric context (the grid's note).
  if (d.shape === "ratio" && context === "metric" && field.target != null) variant = "meter";
  const wanted = context === "text" ? undefined : d.display[context];
  if (wanted !== undefined) {
    if (wanted === null || family.variants[wanted]) {
      variant = wanted;
      source = "field";
    } else warnings.push(`variant "${wanted}" is not a ${d.shape} variant; the grid's "${variant}" is used`);
  }
  let editable = false;
  let control = null;
  let readOnly = d.readOnly;
  if (context === "form") {
    if (mode === "read" || readOnly || !variant || !family.variants[variant]?.editable) {
      // Nothing to edit: the form shows the value as the record row does.
      readOnly = true;
      variant = row.record;
      source = "grid";
    } else editable = true;
  } else if (context !== "text" && mode === "edit" && !readOnly && row.form) {
    editable = true;
    control = row.form;
  }
  const { meta, group } = context === "text" ? { meta: null, group: family.group } : variantMeta(d.shape, variant);
  if (d.shape === "money" && !field.currency && !d.currencyFrom) warnings.push("money without a currency (rule 4): send field.currency or field.currencyFrom");
  const numeric = d.shape === "number" || d.shape === "money" || d.shape === "ratio";
  return {
    shape: d.shape,
    kind: d.kind,
    semanticType: d.semanticType,
    row: row.row,
    context,
    mode,
    variant,
    id: meta?.id ?? null,
    label: context === "text" ? (variant ? rules.textFormats[variant] ?? null : null) : (meta?.label ?? null),
    group,
    parts: meta?.parts ?? [],
    editable,
    control,
    readOnly,
    align: row.align?.[context] ?? "start",
    figures: numeric && (context === "cell" || context === "record") ? "tabular" : null,
    grouping: numeric ? row.grouping !== false : null,
    mono: Boolean(row.mono),
    max: row.max?.[context] ?? null,
    avatar: d.shape === "entity" && context !== "text" ? avatarOf(d.kind, variant) : null,
    multiple: d.multiple,
    unit: d.unit,
    currency: d.shape === "money" ? (field.currency ?? null) : null,
    currencyFrom: d.shape === "money" ? d.currencyFrom : null,
    optionSet,
    ramp: Boolean(row.ramp && optionSet?.options.some((o) => o.ramp)),
    sort: optionSet?.ordinal ? "order" : null,
    last: meta?.last ?? null,
    excluded: row.excluded ?? [],
    text: row.text ?? null,
    formula: d.formula,
    empty: EMPTY,
    source,
    warnings,
  };
}

const pad = (n) => String(n).padStart(2, "0");
const asDate = (v) => (v instanceof Date ? v : typeof v === "number" ? new Date(v) : null);

/** Seconds as an ISO 8601 duration: 30840 → PT8H34M. */
export function isoDuration(seconds) {
  let s = Math.round(Math.abs(Number(seconds)));
  if (!Number.isFinite(s)) return "";
  const d = Math.floor(s / 86400); s -= d * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  const time = `${h ? `${h}H` : ""}${m ? `${m}M` : ""}${s ? `${s}S` : ""}`;
  return `${Number(seconds) < 0 ? "-" : ""}P${d ? `${d}D` : ""}${time ? `T${time}` : d ? "" : "T0S"}`;
}

const SECONDS = { s: 1, min: 60, h: 3600, d: 86400, ms: 0.001 };

/**
 * A value's text form: the plain string for CSV export, aria-label, copy and search (the text context, decision 8).
 * Returns null when the value has no text form (a secret: never its value, export included), "" when it is empty.
 *   textOf({ semanticType: "fiat_amount", currency: "USD" }, 1250)   → "1,250.00 USD"
 *   textOf({ semanticType: "duration_minutes" }, 514)                → "PT8H34M"
 *   textOf({ semanticType: "api_key_secret_ref" }, "vault:…")        → null
 * Money takes its currency from the value ({ amount, currency }), the field (currency) or opts.currency.
 */
export function textOf(field = {}, value, opts = {}) {
  const r = resolveValue(field, "text", "read", opts);
  const format = r.variant;
  if (format == null) return null;
  if (isEmpty(value)) return "";
  const list = (v) => (Array.isArray(v) ? v : [v]);
  const labelOf = (v) => {
    if (v && typeof v === "object") return String(v.label ?? v.value ?? "");
    return r.optionSet?.options.find((o) => String(o.value) === String(v))?.label ?? String(v);
  };
  const nameOf = (e) => (e && typeof e === "object" ? String(e.label ?? e.name ?? e.id ?? "") : String(e));
  switch (format) {
    case "label": return labelOf(value);
    case "labels": return list(value).map(labelOf).join(", ");
    case "name": return nameOf(value);
    case "names": return list(value).map(nameOf).join(", ");
    case "amount-code": {
      const amount = Number(value && typeof value === "object" ? value.amount : value);
      const code = (value && typeof value === "object" ? value.currency : null) ?? field.currency ?? opts.currency ?? null;
      const figure = new Intl.NumberFormat("en-US", { minimumFractionDigits: 2, maximumFractionDigits: r.kind === "crypto" ? 8 : 2 }).format(amount);
      const suffix = code ?? r.unit;
      return suffix ? `${figure} ${suffix}` : figure;
    }
    case "percent": return `${new Intl.NumberFormat("en-US", { maximumFractionDigits: 2, useGrouping: false }).format(Number(value))}%`;
    case "last": {
      const values = Array.isArray(value) ? value : Array.isArray(value?.values) ? value.values : [value];
      return values.length ? String(values[values.length - 1]) : "";
    }
    case "iso-duration": {
      if (typeof value === "string" && /^-?P/.test(value)) return value;
      return isoDuration(Number(value) * (SECONDS[r.unit ?? "s"] ?? 1));
    }
    case "digits": return typeof value === "bigint" ? value.toString() : String(value);
    case "number-unit": return r.unit ? `${value} ${r.unit}` : String(value);
    case "iso-date": {
      const dt = asDate(value);
      return dt ? dt.toISOString().slice(0, 10) : String(value).slice(0, 10);
    }
    case "time": {
      const dt = asDate(value);
      return dt ? `${pad(dt.getHours())}:${pad(dt.getMinutes())}` : String(value).slice(0, 5);
    }
    case "iso-datetime": {
      const dt = asDate(value);
      return dt ? dt.toISOString().replace(/\.\d{3}Z$/, "Z") : String(value);
    }
    case "file-names": return list(value).map((f) => (f && typeof f === "object" ? String(f.name ?? f.filename ?? f.label ?? "") : String(f))).join(", ");
    case "yes-no": return value ? "Yes" : "No";
    case "plain":
      return String(value)
        .replace(/<[^>]*>/g, " ")
        .replace(/!?\[([^\]]*)\]\([^)]*\)/g, "$1")
        .replace(/[*_`~#>]+/g, "")
        .replace(/\s+/g, " ")
        .trim();
    case "json": return typeof value === "string" ? value : JSON.stringify(value);
    case "place": return placeLines(value).join(", ");
    default: return value && typeof value === "object" ? JSON.stringify(value) : String(value);
  }
}

/** A place value's address lines (VAL-12): { lines } or { address }, a list, or a string with a line break per line. */
export function placeLines(value) {
  const v = value && typeof value === "object" && !Array.isArray(value) ? value.lines ?? value.address ?? [] : value;
  return (Array.isArray(v) ? v : String(v ?? "").split(/\n/)).map((l) => String(l).trim()).filter(Boolean);
}

/** The contexts a viewer may re-display a value in (the column display menu): cell, record and card. */
export const CHOICE_CONTEXTS = Object.freeze(["cell", "record", "card"]);

/**
 * The variants a viewer may pick for a field in a context (decision 9, the column display menu), the field's own
 * first: [{ variant, id, label, default }]. From the grid row's `choices` (display-rules.json version 3); a secret
 * offers none, a meter needs the field's target, and the metric and form contexts offer no choice (empty list).
 * A list of one means there is nothing to choose: a surface shows no menu.
 */
export function variants(field = {}, context = "cell", opts = {}) {
  if (!CHOICE_CONTEXTS.includes(context)) return [];
  const r = resolveValue(field, context, "read", opts);
  if (!r.variant) return [];
  const row = rules.grid.find((g) => g.row === r.row);
  let list = [...(row?.choices?.[context] ?? [r.variant])];
  if (r.shape === "ratio" && field.target == null) list = list.filter((v) => v !== "meter");
  if (!list.length) return [];
  if (!list.includes(r.variant)) list.unshift(r.variant);
  else list = [r.variant, ...list.filter((v) => v !== r.variant)];
  const family = rules.variants[r.shape];
  return list.map((v) => {
    const { meta } = variantMeta(r.shape, v);
    return { variant: v, id: meta?.id ?? null, label: meta?.label ?? v, default: v === r.variant };
  });
}
